def win(w, l):
    # w wins a finished game against l (both non-negative):
    # 21-19 or lower, or 22..29 with a lead of exactly 2, or 30 with l <= 29
    return Or(
        And(w == 21, l <= 19),
        And(w >= 22, w <= 29, w - l == 2),
        And(w == 30, l <= 29),
    )

def valid(x, y):
    # the score x:y is a final score with either side winning
    return Or(win(x, y), win(y, x))

def post(a, r):
    v1 = valid(a[0], a[1])
    v2 = valid(a[2], a[3])
    return r == If(v1, 1, 0) + If(v2, 1, 0)
